interface Store {
  orders: Record<string, { state: string }>;
  outboxRows: Array<{ orderId: string; fromState: string; toState: string }>;
  transaction(fn: () => void): void;
}

function recordStateChange(store: Store, orderId: string, toState: string): void {
  store.transaction(() => {
    const fromState = store.orders[orderId].state;
    store.orders[orderId].state = toState;
    store.outboxRows.push({ orderId, fromState, toState });
  });
}

