interface PublishStore {
  pendingRows: Array<{ id: string }>;
  publishedIds: string[];
}

function markPublished(store: PublishStore, subscriberResults: boolean[]): void {
  store.pendingRows.forEach((row, i) => {
    if (subscriberResults[i]) {
      store.publishedIds.push(row.id);
    }
  });
}

