interface SagaStep {
  forward: () => boolean;
  compensate: () => void;
}

function runSaga(steps: SagaStep[]): boolean {
  const succeeded: SagaStep[] = [];

  for (const step of steps) {
    const ok = step.forward();
    if (!ok) {
      for (let i = succeeded.length - 1; i >= 0; i--) {
        succeeded[i].compensate();
      }
      return false;
    }
    succeeded.push(step);
  }

  return true;
}

