interface ForwardStep {
  forward: () => boolean;
}

function firstFailureIndex(steps: ForwardStep[]): number {
  for (let i = 0; i < steps.length; i++) {
    if (!steps[i].forward()) {
      return i;
    }
  }
  return -1;
}

